function formatData(rawData) {
  if (!rawData || !Array.isArray(rawData)) {
    return { success: false, message: '无效的数据格式' };
  }

  const formattedData = rawData.map((item, index) => ({
    id: index + 1,
    ...item,
    processedAt: new Date().toISOString()
  }));

  return {
    success: true,
    data: formattedData,
    count: formattedData.length
  };
}

